program VmArrayPushBenchmark;

uses Std.Args, Std.Array, Std.Console, Std.Conv, Std.Time;

const
  WarmupIterations: integer := 100000;

function RunPush(Iterations: integer): integer;
begin
  mutable var Values: array of integer := [];
  for Index: integer := 1 to Iterations do
  begin
    Std.Array.Push(Values, Index)
  end;

  return Std.Array.Length(Values)
end;

begin
  if (ParamCount() < 1) or (ParamCount() > 2) then
  begin
    panic('usage: array_push_benchmark.fpas -- ITERATIONS [MAX_MILLIS]')
  end;
  var Iterations: integer := StrToInt(ParamStr(0));
  if Iterations < 1 then
  begin
    panic('ITERATIONS must be positive')
  end;
  mutable var MaxMillis: integer := 0;
  if ParamCount() = 2 then
  begin
    MaxMillis := StrToInt(ParamStr(1));
    if MaxMillis < 1 then
    begin
      panic('MAX_MILLIS must be positive')
    end
  end;
  mutable var Length: integer := RunPush(WarmupIterations);
  var Started: integer := MonotonicMillis();
  Length := RunPush(Iterations);
  var Elapsed: integer := ElapsedMillis(Started);
  mutable var OpsPerSecond: integer := Iterations;
  if Elapsed > 0 then
  begin
    OpsPerSecond := (Iterations * 1000) div Elapsed
  end;

  WriteLn((('iterations: ' + IntToStr(Iterations)) + ', warm-up: ') + IntToStr(WarmupIterations));
  WriteLn(('elapsed: ' + IntToStr(Elapsed)) + ' ms');
  WriteLn(('throughput: ' + IntToStr(OpsPerSecond)) + ' pushes/s');
  WriteLn('final length: ' + IntToStr(Length));
  if (MaxMillis > 0) and (Elapsed > MaxMillis) then
  begin
    panic(((('array-push benchmark regression: ' + IntToStr(Elapsed)) + ' ms exceeds limit ') + IntToStr(MaxMillis)) +
          ' ms')
  end
end.

program NoteTuiWorkflowTest;

uses Notes.Model, Notes.Update, Notes.View, Std.Array, Std.Fs, Std.Str, Std.Test, Std.Tui;

const
  Root: string := '.temp-data';
  Directory: string := Root + '/notes-tui-test';

procedure EnsureRoot();
begin
  if not Std.Fs.Exists(Root) then
  begin
    case Std.Fs.CreateDir(Root) of
      Ok(Created):
      begin
      end;
      Error(Message):
      begin
        Fail(Message)
      end
    end
  end
end;

function ScreenContains(Snapshot: TuiSurfaceSnapshot; Text: string): boolean;
begin
  for Row: integer := 0 to Snapshot.Height - 1 do
  begin
    if Std.Str.Contains(Snapshot.LineAt(Row), Text) then
    begin
      return true
    end
  end;

  return false
end;

function MakeKey(Kind: TuiKeyKind): TuiKeyEvent;
begin
  return record
    kind := Kind;
    ch := '';
    shift := false;
    ctrl := false;
    alt := false;
    meta := false;
  end
end;

function MakeCtrlKey(Character: string): TuiKeyEvent;
begin
  return record
    kind := TuiKeyKind.Character;
    ch := Character;
    shift := false;
    ctrl := true;
    alt := false;
    meta := false;
  end
end;

function MakeAltKey(Character: string): TuiKeyEvent;
begin
  return record
    kind := TuiKeyKind.Character;
    ch := Character;
    shift := false;
    ctrl := false;
    alt := true;
    meta := false;
  end
end;

begin
  EnsureRoot();
  var EmptyLoaded: NotesLoad := record
    Notes := [];
    Issues := [];
  end;
  mutable var EmptyModel: NotesModel := NotesModelCreate(Directory, EmptyLoaded);
  var EmptyApp: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(100, 24));
  EmptyModel := EmptyApp.RunIterations(EmptyModel, NotesUpdate, NotesView, 0, 0);
  var EmptySnapshot: TuiSurfaceSnapshot := EmptyApp.SurfaceSnapshot();
  AssertEquals('╰', EmptySnapshot.CellAt(0, 22).Glyph);
  AssertEquals('╯', EmptySnapshot.CellAt(32, 22).Glyph);
  AssertEquals('╰', EmptySnapshot.CellAt(33, 22).Glyph);
  AssertEquals('╯', EmptySnapshot.CellAt(99, 22).Glyph);
  AssertTrue(Std.Str.Contains(EmptySnapshot.LineAt(22), '╯╰'));
  EmptyApp.Inject(TuiMsgAction(TuiControlId.Create(20), TuiAction.Create(14)));
  EmptyModel := EmptyApp.RunIterations(EmptyModel, NotesUpdate, NotesView, 1, 0);
  AssertTrue(EmptyModel.Overlay = NotesOverlay.Commands);
  EmptyApp.InjectKeyForTest(MakeKey(TuiKeyKind.Down));
  EmptyModel := EmptyApp.RunIterations(EmptyModel, NotesUpdate, NotesView, 1, 0);
  AssertEquals(24, EmptyModel.Focus);
  EmptyApp.InjectKeyForTest(MakeKey(TuiKeyKind.Enter));
  EmptyModel := EmptyApp.RunIterations(EmptyModel, NotesUpdate, NotesView, 1, 0);
  AssertTrue(EmptyModel.Overlay = NotesOverlay.Help);
  EmptyApp.Close();
  var First: Note := NoteCreate('focus-first', 1);
  var Second: Note := NoteCreate('focus-second', 2);
  var FocusLoaded: NotesLoad := record
    Notes := [First, Second];
    Issues := [];
  end;
  mutable var FocusModel: NotesModel := NotesModelCreate(Directory, FocusLoaded);
  var FocusApp: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(100, 24));
